   [250]={next_id=251, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="The first time she saw those mutilated knights, an indescribable familiarity seized her—one she couldn't voice, because it reminded her of people.", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1001.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [251]={next_id=252, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="People who should have been resting peacefully in their graves.", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1001.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [252]={next_id=253, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="She thought she was just mistaken and didn't believe those people could appear here, and moreover, walking on the ground in a way similar to the undead.", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1001.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [253]={next_id=254, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="But now, the truth was right in front of her.", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1001.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [254]={next_id=255, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="What could explain this? Mad science? Religious rites? Or something even the stars had never foretold...?", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1001.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [255]={next_id=256, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="Or was this just a hallucination, born the moment she stepped into the pilgrimage site?", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1001.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
